begin;
create function pg_temp.submit_fixture(token uuid,school text,request_id uuid default gen_random_uuid(),latitude double precision default 17,longitude double precision default 121,accuracy double precision default 5,captured timestamptz default clock_timestamp(),checkpoint text default 'first',browser text default repeat('a',64),name text default 'Participant One',payload text default repeat('c',64)) returns jsonb language sql as $$
 select public.submit_public_attendance(token,request_id,browser,repeat('b',64),'Synthetic browser',payload,school,name,'ISAP','Class A',checkpoint,latitude,longitude,accuracy,captured,'[[[0.1,0.1],[0.2,0.2],[0.3,0.1],[0.4,0.2],[0.5,0.1],[0.6,0.2],[0.7,0.1],[0.8,0.2]]]','2026-11-26-attendance-v1',true);
$$;
grant execute on function pg_temp.submit_fixture to service_role;
do $$
declare root uuid;staff uuid:=gen_random_uuid();e uuid:=gen_random_uuid();empty_event uuid:=gen_random_uuid();section uuid;course_row public.courses;r jsonb;p jsonb;link jsonb;token uuid;old_token uuid;request_id uuid:=gen_random_uuid();submission uuid;count_students integer;count_users integer;id1 text:='PA-'||left(replace(gen_random_uuid()::text,'-',''),12);i integer;
begin
 root:=(select user_id from public.user_profiles where role='main_admin' and retired_at is null and approval_status='approved');
 select * into strict course_row from public.courses where institution='ISAP' and active order by name limit 1;
 insert into auth.users(id,email,email_confirmed_at) values(staff,staff||'@test.invalid',now());insert into public.user_profiles(user_id,full_name) values(staff,'Staff fixture');
 perform set_config('role','service_role',true);perform public.bootstrap_operational_administrator(root);
 perform public.save_operational_account(root,staff,'col_admin','Staff fixture',true,0,'[{"kind":"institution","scope_id":"ISAP"}]','{}','Fixture provision');
 insert into public.events(id,name,institution,latitude,longitude,radius_meters,starts_at,ends_at) values(e,'Public test','ISAP',17,121,100,now()+interval '2 days',now()+interval '3 days'),(empty_event,'No roster','ISAP',17,121,100,now()+interval '2 days',now()+interval '3 days');
 r:=public.save_class_section(root,null,0,jsonb_build_object('institution','ISAP','college',course_row.college,'course',course_row.name,'name','Public class '||id1,'academic_year','2026-2027','term','First semester'),'Fixture class');section:=(r->>'id')::uuid;
 p:=public.preview_class_roster(root,section,jsonb_build_array(jsonb_build_object('row_number',2,'school_id',upper(id1),'full_name','Participant One'),jsonb_build_object('row_number',3,'school_id',upper(id1)||'-2','full_name','Participant Two')),'official.xlsx','merge');perform public.commit_class_roster(root,(p->>'id')::uuid,false,false,'Fixture roster');
 perform public.set_event_class_rosters(root,e,0,jsonb_build_array(section),'Fixture eligibility');
 begin perform public.save_event_public_link(root,empty_event,0,true,false,'','Publish without official list');raise exception 'FAIL: no-roster event published';exception when sqlstate '22023' then null;end;
 link:=public.save_event_public_link(root,e,0,true,false,'','Publish fixture');token:=(link->>'token')::uuid;
 update public.events set starts_at=now()-interval '1 minute',ends_at=now()+interval '2 hours',checkpoints=jsonb_build_array(jsonb_build_object('key','first','label','Attendance','opens_at',now()-interval '2 minutes','closes_at',now()+interval '2 hours')) where id=e;
 select count(*) into count_students from public.students;
 r:=pg_temp.submit_fixture(token,upper(id1),request_id);submission:=(r->'body'->>'receipt_id')::uuid;
 if (select count(*) from public.participant_device_bindings where student_id=(select student_id from public.public_attendance_submissions where id=submission) and ended_at is null)<>1 or exists(select 1 from public.participant_penalty_ledger) then raise exception 'FAIL: first attendance binding/point';end if;
 perform pg_temp.submit_fixture(token,upper(id1),request_id);
 if (select count(*) from public.participant_device_observations where submission_id=submission)<>1 then raise exception 'FAIL: retry duplicated device evidence';end if;
 perform pg_temp.submit_fixture(token,upper(id1),gen_random_uuid(),18,121,5,clock_timestamp(),'first',repeat('d',64));
 perform pg_temp.submit_fixture(token,upper(id1),gen_random_uuid(),17,121,5,clock_timestamp(),'first',repeat('d',64),'Wrong name');
 if exists(select 1 from public.participant_device_incidents) then raise exception 'FAIL: invalid location or mismatched identity created device incident';end if;
 perform pg_temp.submit_fixture(token,upper(id1),gen_random_uuid(),17,121,5,clock_timestamp(),'first',repeat('d',64));
 perform pg_temp.submit_fixture(token,upper(id1),gen_random_uuid(),17,121,5,clock_timestamp(),'first',repeat('d',64));
 if (select count(*) from public.participant_device_incidents where kind='device_change')<>1 or (select sum(points) from public.participant_penalty_ledger)<>1 or not exists(select 1 from public.participant_device_bindings where device_hash=repeat('a',64) and ended_at is null) then raise exception 'FAIL: device change deduplication or silent replacement';end if;
 perform pg_temp.submit_fixture(token,upper(id1),gen_random_uuid(),17,121,5,clock_timestamp(),'first',repeat('e',64));
 begin perform public.list_participant_device_incidents(staff,e,1);raise exception 'FAIL: lower role can read sensitive device evidence';exception when insufficient_privilege then null;end;
 p:=public.list_participant_device_incidents(root,e,1);if (p->>'total')::int<>2 then raise exception 'FAIL: administrator incident list';end if;
 select id into old_token from public.participant_device_incidents where candidate_device=repeat('d',64);
 begin perform public.resolve_participant_device_incident(root,old_token,1,'replace','Verified participant',false);raise exception 'FAIL: replacement without confirmation';exception when sqlstate '22023' then null;end;
 p:=public.resolve_participant_device_incident(root,old_token,1,'replace','Verified participant and replacement browser',true);
 if (p->'incident'->>'state') is distinct from 'replaced' or (select count(*) from public.participant_device_bindings where ended_at is not null)<>1 or not exists(select 1 from public.participant_device_bindings where device_hash=repeat('d',64) and ended_at is null and actor_user_id=root) or (select sum(points) from public.participant_penalty_ledger)<>2 then raise exception 'FAIL: audited replacement or point retention';end if;
 begin perform public.resolve_participant_device_incident(root,old_token,1,'dismiss','Retry decision',true);raise exception 'FAIL: stale reviewer overwrote decision';exception when serialization_failure then null;end;
 select id into old_token from public.participant_device_incidents where candidate_device=repeat('e',64);
 begin perform public.resolve_participant_device_incident(root,old_token,1,'replace','Stale binding replacement',true);raise exception 'FAIL: obsolete candidate replaced new binding';exception when serialization_failure then null;end;
 perform public.resolve_participant_device_incident(root,old_token,1,'dismiss','Confirmed false flag',true);
 if (select sum(points) from public.participant_penalty_ledger)<>1 or (select count(*) from public.participant_penalty_ledger)<>3 then raise exception 'FAIL: false flag did not append adjustment';end if;
 perform pg_temp.submit_fixture(token,upper(id1),request_id);
 if (select count(*) from public.participant_device_incidents)<>2 then raise exception 'FAIL: original request replay flagged old device';end if;
 r:=pg_temp.submit_fixture(token,upper(id1)||'-2',gen_random_uuid(),17,121,5,clock_timestamp(),'first',repeat('d',64),'Participant Two');
 if (select count(*) from public.participant_device_incidents where kind='shared_browser')<>2 or (select sum(points) from public.participant_penalty_ledger)<>1 or (select count(*) from public.participant_device_bindings where ended_at is null)<>1 then raise exception 'FAIL: shared browser not held or charged extra point/bound identity';end if;
 perform pg_temp.submit_fixture(token,'MISSING-'||upper(id1),gen_random_uuid(),17,121,5,clock_timestamp(),'first',repeat('d',64),'Unknown identity');
 if (select count(*) from public.participant_device_incidents)<>4 or (select count(*) from public.students)<>count_students then raise exception 'FAIL: missing roster seized a binding or flagged a participant';end if;
 if exists(select 1 from public.public_attendance_submissions where event_id=e and status='approved') then raise exception 'FAIL: device decision approved attendance';end if;
 begin update public.participant_penalty_ledger set reason='Tamper';raise exception 'FAIL: penalty evidence mutable';exception when sqlstate '22023' then null;end;
 begin delete from public.participant_device_observations;raise exception 'FAIL: device observation deletable';exception when sqlstate '22023' then null;end;
 if has_table_privilege('anon','public.participant_device_observations','SELECT') or has_table_privilege('authenticated','public.participant_penalty_ledger','SELECT') or has_function_privilege('authenticated','public.get_participant_device_incident(uuid,uuid)','EXECUTE') then raise exception 'FAIL: device evidence exposed to browser roles';end if;
end $$;
rollback;
